"""Learner-review corrections: actual prompts, answers and independent credit points."""
CARDS={};PARTS={};NEW=[]
def card(k,p,a,g,ao=None,sub=None,bloom=None,recall=None,objectives=None):
 CARDS[k]=dict(prompt=p,canonical_answer=a,marking_guidance=g.split('|'),ao=ao,sub=sub,bloom=bloom,recall=recall,objectives=objectives)
def part(k,p,a=None,g=None,recall=None,ao=None,bloom=None,objectives=None):
 PARTS[k]=dict(prompt=p,canonical_answer=a,marking_guidance=g.split('|') if g else None,recall=recall,ao=ao,bloom=bloom,objectives=objectives)
def new(t,obj,p,a,g,sub='APP',ao='B',bloom='Apply',recall=0):
 NEW.append(dict(topic=t,objectives=obj.split('|'),prompt=p,canonical_answer=a,marking_guidance=g.split('|'),sub=sub,ao=ao,bloom=bloom,recall=recall))
